/* Lot 107: relative heights and max-height on the box scrollers of the reader (generated by scripts/lot107_gen.py; expectations from scripts/lot107_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><div id=b><p id=i>i</p><p id=r>r</p></div></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(8, g_d.nnodes);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

/* overflow-x, overflow-y, the absolute height and max-height kept
 * (px + 1), scr, the font size */
static const char *sc_of(int k) {
    const wf_site_node_t *n = &g_d.node[k];
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d", n->ov[0], n->ov[1], n->hpx, n->mpx, n->scr, g_d.fs[k]);
    return g_o;
}

static void test_l107_height_0(void) {
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } div { overflow: scroll; max-height: 3rem !important } #b { max-height: 5; overflow: hidden auto } #o { height: calc(10px + 5px); overflow: visible scroll }  #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("1 5 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("2 4 0 0 1 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:auto;max-height:48px\"", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } div { overflow: auto } #o { overflow: auto } #b { height: min-content }  #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("4 4 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("4 4 0 0 1 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { height: 1in; overflow: hidden !important } #o { max-height: 247px; height: 75pt; overflow: visible; height: 12.5% } html { font-size: 12px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("1 1 0 248 0 12000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("2 2 97 0 1 12000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { max-height: calc(10px - 20px) !important; height: auto } #b { overflow: auto; height: 104%; max-height: 391px !important }  #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("0 0 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("4 4 0 392 1 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:auto;height:104%;max-height:391px\"", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { overflow: clip; height: 0.5in; max-height: 10em! } #o { max-height: calc(1px+2px); overflow: hidden }  #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("2 2 0 0 1 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("3 3 49 0 0 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow: visible scroll; height: 12.5% } #b { overflow: hidden auto; max-height: 10ex } html { font-size: 24px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) } #r { animation: k 1s linear; animation-timeline: view() }");
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("1 5 0 0 0 24000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("2 4 0 0 1 24000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:auto;max-height:80px\"", style_of("b"));
}

